<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { hotelApi } from '../../api'
import { errorMessage } from '../../api/client'

type IntentRecord = Record<string, any>
const items = ref<IntentRecord[]>([])
const loading = ref(false)
const selected = ref<IntentRecord | null>(null)
const drawerVisible = ref(false)
const actionLoading = ref(false)
const newCount = computed(() => items.value.filter((item) => item.intent_status === 'NEW').length)
const totalReserved = computed(() => items.value.reduce((sum, item) => sum + 1, 0))

async function load() {
  loading.value = true
  try { items.value = (await hotelApi.intents()).data }
  catch (e) { ElMessage.error(errorMessage(e)) }
  finally { loading.value = false }
}
function open(item: IntentRecord) { selected.value = item; drawerVisible.value = true }
function timeText(value?: string) { return value ? String(value).slice(0, 5) : '未填写' }
function dateText(value?: string) { return value ? String(value).replace('T', ' ').slice(0, 16) : '—' }
function listText(value?: unknown[], fallback = '未填写') { return Array.isArray(value) && value.length ? value.join('、') : fallback }
async function updateIntent(status: 'CONFIRMED' | 'CANCELLED') {
  if (!selected.value) return
  actionLoading.value = true
  try { await hotelApi.updateIntent(Number(selected.value.id), status); ElMessage.success(status === 'CONFIRMED' ? '预约意向已确认，资源继续占用' : '预约意向已取消，库存已释放'); drawerVisible.value = false; await load() }
  catch (e) { ElMessage.error(errorMessage(e)) }
  finally { actionLoading.value = false }
}
onMounted(load)
</script>

<template>
  <div class="intent-page">
    <div class="page-head"><div><div class="eyebrow">VISITOR INTENTS · LEADS</div><h1>游客预约意向</h1><p>把游客说过的话、联系人和库存占用放在一起，酒店可以直接跟进确认。</p></div><div class="header-actions"><span class="live-pill"><i /> {{ newCount }} 条待跟进</span><el-button plain @click="load">刷新</el-button></div></div>
    <div class="intent-summary"><div><span>NEW LEADS</span><strong>{{ newCount }}</strong><small>待联系游客</small></div><div><span>RESERVED MOMENTS</span><strong>{{ totalReserved }}</strong><small>预约意向暂占用套餐</small></div><div><span>FOLLOW-UP</span><strong>人工确认</strong><small>过敏、儿童安全和场次仍需核对</small></div></div>
    <div class="panel table-wrap intent-table-panel"><el-table v-loading="loading" :data="items" row-class-name="intent-row" @row-click="open"><el-table-column label="产品" min-width="230"><template #default="{row}"><div class="intent-product"><span class="intent-product__mark">S</span><div><strong>{{ row.product_name }}</strong><small>{{ row.product_code || `产品 #${row.product_id}` }} · {{ row.target_date }}</small></div></div></template></el-table-column><el-table-column label="同行需求" min-width="180"><template #default="{row}"><strong>{{ row.adult_count }} 成人 · {{ row.child_count }} 儿童</strong><small class="table-subline">{{ row.child_ages?.length ? `儿童 ${row.child_ages.join('、')} 岁` : '未提供儿童年龄' }}</small></template></el-table-column><el-table-column label="预算 / 体验" min-width="170"><template #default="{row}"><strong>¥{{ row.budget }}</strong><small class="table-subline">{{ listText(row.interests, '杭州文化体验') }}</small></template></el-table-column><el-table-column label="联系人" min-width="150"><template #default="{row}"><strong>{{ row.contact_name }}</strong><small class="table-subline">{{ row.contact_phone }}</small></template></el-table-column><el-table-column label="库存" width="100"><template #default="{row}"><span :class="row.remaining_quantity <= 2 ? 'warning-text' : 'success-text'">余 {{ row.remaining_quantity }} 套</span></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag type="warning" effect="light">{{ row.intent_status === 'NEW' ? '待跟进' : row.intent_status }}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click.stop="open(row)">查看详情</el-button></template></el-table-column></el-table><div v-if="!loading && !items.length" class="empty-state">游客提交预约意向后，会在这里形成可跟进的真实线索。</div></div>

    <el-drawer v-model="drawerVisible" title="预约意向详情" size="520px"><div v-if="selected" class="intent-drawer"><div class="intent-drawer__product"><span class="intent-product__mark">S</span><div><div class="eyebrow">{{ selected.product_code || `产品 #${selected.product_id}` }}</div><h2>{{ selected.product_name }}</h2><p>{{ selected.target_date }} · 当前余 {{ selected.remaining_quantity }} 套 · ¥{{ selected.submitted_price || selected.budget }}</p></div></div><div class="drawer-section"><div class="drawer-label">同行信息</div><div class="drawer-grid"><div><span>成人</span><strong>{{ selected.adult_count }} 位</strong></div><div><span>儿童</span><strong>{{ selected.child_count }} 位</strong></div><div><span>儿童年龄</span><strong>{{ listText(selected.child_ages) }}</strong></div><div><span>预算</span><strong>¥{{ selected.budget }}</strong></div></div></div><div class="drawer-section"><div class="drawer-label">偏好与注意事项</div><div class="drawer-tags"><span v-for="item in [...(selected.interests || []), ...(selected.dietary_restrictions || [])]" :key="item">{{ item }}</span><span v-if="selected.allergy_information" class="safety-tag">{{ selected.allergy_information }}</span><span v-if="!selected.interests?.length && !selected.dietary_restrictions?.length && !selected.allergy_information">未填写特殊偏好</span></div><p v-if="selected.preferred_experience_time" class="drawer-note">希望体验时间：{{ timeText(selected.preferred_experience_time) }}</p></div><div class="drawer-section drawer-quote"><div class="drawer-label">游客原话</div><p>“{{ selected.other_requirements || '游客未补充自然语言需求。' }}”</p></div><div class="drawer-section"><div class="drawer-label">联系方式</div><div class="contact-card"><strong>{{ selected.contact_name }}</strong><span>{{ selected.contact_phone }}</span><small>提交于 {{ dateText(selected.created_at) }}</small></div></div><div class="drawer-actions"><div class="follow-up-note"><span class="follow-up-note__dot"></span><div><strong>{{ selected.reservation_status === 'HELD' ? '待人工跟进确认' : selected.reservation_status }}</strong><small>确认前请核对场次、儿童安全与过敏信息；保留到 {{ dateText(selected.reserved_until) }}。</small></div></div><div v-if="selected.reservation_status === 'HELD'" class="intent-action-row"><el-button type="primary" :loading="actionLoading" @click="updateIntent('CONFIRMED')">确认预约意向</el-button><el-button plain :loading="actionLoading" @click="updateIntent('CANCELLED')">释放占用</el-button></div><small>比赛版本不执行支付，预约意向仅作为真实经营线索和库存暂占记录。</small></div></div></el-drawer>
  </div>
</template>

<style scoped>
.intent-page{max-width:1280px}.header-actions{display:flex;align-items:center;gap:10px}.intent-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:22px 0}.intent-summary>div{padding:18px 20px;background:#fff;border:1px solid var(--line);border-radius:14px}.intent-summary span{display:block;color:#789087;font-size:10px;letter-spacing:.12em}.intent-summary strong{display:block;font:28px Georgia,serif;color:var(--teal-dark);margin:9px 0 4px}.intent-summary small{color:var(--muted);font-size:11px}.intent-table-panel{padding:8px 18px 18px}.intent-table-panel :deep(.el-table__row){cursor:pointer}.intent-product{display:flex;align-items:center;gap:10px}.intent-product__mark{width:30px;height:30px;display:grid;place-items:center;border-radius:10px;background:#e6f3ed;color:var(--teal);font:19px Georgia,serif}.intent-product strong,.intent-product small,.table-subline{display:block}.intent-product small,.table-subline{color:var(--muted);font-size:11px;margin-top:5px}.success-text{color:#438765;font-size:12px;font-weight:600}.intent-drawer{padding:0 4px 20px}.intent-drawer__product{display:flex;gap:13px;padding-bottom:23px;border-bottom:1px solid var(--line)}.intent-drawer__product h2{font:25px Georgia,serif;margin:7px 0}.intent-drawer__product p{color:var(--muted);font-size:12px;margin:0}.drawer-section{padding:23px 0;border-bottom:1px solid var(--line)}.drawer-label{color:var(--teal);font-size:10px;font-weight:700;letter-spacing:.14em;margin-bottom:14px}.drawer-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.drawer-grid span,.contact-card span,.contact-card small{display:block;color:var(--muted);font-size:11px}.drawer-grid strong{display:block;margin-top:5px;font-size:14px}.drawer-tags{display:flex;gap:7px;flex-wrap:wrap}.drawer-tags span{padding:7px 10px;border-radius:999px;background:#eef7f1;color:var(--teal-dark);font-size:12px}.drawer-tags .safety-tag{background:#fff4df;color:#a26e2b}.drawer-note{color:var(--muted);font-size:12px;margin:14px 0 0}.drawer-quote{background:#f6faf7;margin:0 -4px;padding:20px 16px}.drawer-quote p{font:17px/1.8 Georgia,'Songti SC',serif;color:var(--ink);margin:0}.contact-card{display:grid;gap:5px;padding:13px;background:#fbf3e5;border-radius:12px}.contact-card strong{font-size:16px}.drawer-actions{padding-top:20px}.drawer-actions>small{display:block;text-align:center;color:var(--muted);font-size:10px;margin-top:9px}.follow-up-note{display:flex;gap:10px;align-items:flex-start;padding:13px 14px;border:1px solid #dcece3;background:#f4faf6;border-radius:12px}.follow-up-note__dot{width:8px;height:8px;border-radius:50%;background:#d59f4d;box-shadow:0 0 0 4px #f7ead4;margin:5px 2px 0 3px;flex:none}.follow-up-note strong,.follow-up-note small{display:block}.follow-up-note strong{font-size:13px;color:var(--teal-dark)}.follow-up-note small{margin-top:4px;color:var(--muted);font-size:11px;line-height:1.6}.intent-action-row{display:flex;gap:9px;flex-wrap:wrap;margin-top:16px}@media(max-width:800px){.intent-summary{grid-template-columns:1fr}.header-actions{margin-top:12px}.page-head{display:block}}
</style>
